'use strict';
// Optional, local-only story trails. Original 84-card deck stays unchanged.
const Treasure17={
 passages:Road.parse(TREASURE17_SCRIPTURE_MD,'scripture'),images:new Map(),reading:null,bookPage:0,
 items:{'q17-royal-receipt':{name:'The King’s cancelled bond',kind:'The Cancelled Bond · freely received',text:'The Son’s payment is complete. Two branch impressions at Freed Quay identify the receipt; they do not pay the debt. North from Brass Gully.'},'q17-quay-medallion':{name:'Medallion of the open quay',kind:'Treasure · The Cancelled Bond',text:'A small silver sun within a broken ring. Harven gave it freely from the reopened boat chest.'},'q17-garden-key':{name:'Neris’s garden key',kind:'The Garden Key · return to Neris',text:'Found beside the Lantern Garden arch. It belongs to Neris. She waits just north of the arch; Rook has no claim to it.'},'q17-seed-lantern':{name:'The seed-keeper’s lantern',kind:'Treasure · The Garden Key',text:'A green-glass lantern and three seed envelopes, given by Neris after the watering channels were restored. Her key stays hers.'}},
 fresh(){return{bond:{receipt:false,west:false,east:false,recalled:false,open:false,treasure:false},garden:{key:false,returned:false,permission:false,help:false,recalled:false,watered:false,treasure:false,wheels:[0,0,0]},recalls:{}};},
 restore(raw){const q=this.fresh();for(const group of ['bond','garden'])for(const key of Object.keys(q[group]))if(typeof q[group][key]==='boolean')q[group][key]=raw?.[group]?.[key]===true;q.garden.wheels=[0,1,2].map(i=>Number.isInteger(raw?.garden?.wheels?.[i])?Math.max(0,Math.min(3,raw.garden.wheels[i])):0);for(const c of this.passages)if(Number.isInteger(raw?.recalls?.[c.id]))q.recalls[c.id]=Math.max(0,Math.min(100000,raw.recalls[c.id]));return q;},
 q(){return state.treasure17??=this.fresh();},
 give(id){if(!state.items.includes(id))state.items.push(id);},
 save(){persist();hud();},
 applyGate(q){const s=OPENING_WORLD.regions['freed-quay'];if(s){s.terrain.blocked=s.terrain.blocked.filter(p=>p.id!=='q17-claim-barrier');if(!q.bond.open)s.terrain.blocked.push(s.closedGate);}},
 sync(){this.applyGate(this.q());if(OPENING_WORLD.regions[state.region]?.treasure17)$('#game-stage .hud .eyebrow').textContent='THE TIDEGLASS TREASURE TRAILS';},
 panel(title,body,actions='',label='A TREASURE TRAIL'){show(`<h2 id="panel-title">${title}</h2>${body}<div class="actions">${actions}<button data-action="close">Keep exploring</button></div>`,'treasure17',label);},
 button(action,text,id='',primary=false){return `<button ${primary?'class="primary" ':''}data-action="${action}" data-id="${id}">${text}</button>`;},
 readingMenu(lesson){const choices=this.passages.filter(c=>c.lesson===lesson);this.panel(lesson==='bond'?'A debt already answered':'Loved before the work',`<p>${lesson==='bond'?'Erelis unfolds the King’s receipt. “The Son entered the prison freely, bore its cost, and broke the creditor’s claim. These words tell of Christ himself, beyond our tale.”':'Neris sets out three seed envelopes. “The King’s Son welcomed me before I had a garden worth showing. I can offer you friendship without buying yours.”'}</p><p>Choose a passage. Read it in full before a short, untimed recall. Hints and every input mode remain available.</p>`,choices.map(c=>this.button('q17-read',esc(c.title),c.id)).join(''),'WORDS FOR THE ROAD');},
 read(id){const c=this.passages.find(c=>c.id===id);if(!c)return;this.reading=id;this.panel(esc(c.title),`<blockquote class="verse">${rich(c.text)}</blockquote><p>${c.lesson==='bond'?'The cross and Christ’s victory come first. The receipt pictures a completed gift; the hunt does not buy forgiveness.':'God’s love comes first; freedom becomes loving service. A friend’s “no” is a boundary to honor, not a challenge to defeat.'}</p><p class="hint">KJV · ${c.id==='treasure-cancelled-bond'?'“Quickened” means made alive; “spoiled” here means disarmed.':c.id==='treasure-free-to-serve'?'“Liberty” means freedom; “the flesh” here concerns sinful self-rule, not bodies being bad.':c.id==='treasure-gift-before-work'?'Grace is God’s freely given favor. Good works follow the gift; they do not buy it.':'Our response of love follows God’s prior love.'} The fiction and this explanation are separate from the quoted passage.</p>`,this.button('q17-recall','Ready — recall the headline',id,true)+this.button('q17-readings','Choose another passage',c.lesson),'READ TOGETHER');},
 recall(id){const c=this.passages.find(c=>c.id===id);if(!c||id!==this.reading)return;const unit=Road.units(c,'summary')[0],halves=Road.halves(unit.text),opening=((this.q().recalls[id]||0)%2)===1,target=halves[opening?0:1],cue=halves[opening?1:0],puzzle=Exploration.puzzle(target,state.settings.difficulty==='hard',this.passages.filter(p=>p.id!==id).map(p=>Road.plain(p.summary)));g.battle=null;g.practiceRun=null;g.exercise={id,scope:'summary',index:0,unit,opening,target,cue,parts:puzzle.parts,pool:puzzle.pool,selected:[],answer:'',done:false,helped:false,treasure17:c.lesson};practiceView();},
 recalled(ex){const c=this.passages.find(c=>c.id===ex.id);if(!c||!ex.treasure17)return false;this.q().recalls[c.id]=(this.q().recalls[c.id]||0)+1;this.q()[c.lesson].recalled=true;if(c.lesson==='garden'){const a=this.q().garden;if(a.permission&&a.help&&a.wheels.join()==='2,1,2')a.watered=true;}g.exercise=null;this.save();this.panel('Carry the words into the choice',`<p>${c.lesson==='bond'?'The payment is already complete. Find both branch impressions, then show the receipt at the bridge. Refuse the second demand without treating Harven as your enemy.':this.q().garden.watered?'The wheels agree and the intake opens. Find Neris’s chest by the northern path.':'You can give back the key and help with the water without purchasing a friendship or taking charge of Neris’s garden.'}</p>`,this.button('q17-journal','See my next step'),'WORDS REMEMBERED');return true;},
 journal(){const q=this.q();this.panel('Two trails from Tideglass',`<p><strong>The Cancelled Bond</strong><br>${!q.bond.receipt?'Speak to Erelis beside the Brass Gully bell lift.':!q.bond.west||!q.bond.east?'Freed Quay, north of Brass Gully: inspect both branch impressions on the lower bank.':!q.bond.recalled?'Read with Erelis, or at the quay’s bridge, then recall a headline.':!q.bond.open?'At Freed Quay’s bridge, present the completed receipt.':!q.bond.treasure?'Cross the bridge and open the chest on the northern mosaic.':'Complete. The silver medallion is in Objects & errands.'}</p><p><strong>The Garden Key</strong><br>${!q.garden.key&&!q.garden.returned?'Go north from Drowned Orchard. Look beside the west pier of the garden arch for Neris’s key.':!q.garden.returned?'Give the key to Neris, just north of the arch.':!q.garden.help?'Ask Neris to help you with the water.':!q.garden.recalled?'Read and recall a life-giving passage with Neris.':!q.garden.watered?'Turn the spring wheel south, west wheel east and east wheel south. Walk to each stone socket.':!q.garden.treasure?'Find Neris’s chest beside the northern path.':'Complete. The seed-keeper’s lantern is in Objects & errands.'}</p><p class="hint">Rill’s ferry returns from Tideglass’s southern landing. No treasure trail consumes your original way-cards.</p>`,this.button('q17-export','Download the separate Scripture readings'));},
 visit(id){if(!id.startsWith('q17-'))return false;this.sync();const q=this.q(),b=q.bond,a=q.garden;
  if(id==='q17-maerin'){b.receipt=true;this.give('q17-royal-receipt');this.save();this.panel('Erelis',`<p class="npc-role">Quay archivist · keeper of the cancelled bond</p><p>“Your name is on no new bargain,” she says, placing the receipt in your hand. “The King’s Son settled the bond—the old debt-paper—before you came. He passed through the creditor’s prison and came out with its keys.”</p><p>“A whisper still collects the old toll. Take this freely. North, on the lower quay, two branch impressions will show Harven its seal. The bell box here is separate salvage; you need not buy this release.”</p>`,this.button('q17-readings','Read the words beside the receipt','bond',true)+this.button('q17-journal','Track the treasure trails'),'THE CANCELLED BOND');return true;}
  if(id==='q17-quay-sign'||id==='q17-garden-sign'||id==='q17-garden-leaf'){this.journal();return true;}
  if(id==='q17-west-seal'||id==='q17-east-seal'){b[id.includes('west')?'west':'east']=true;this.save();this.panel('A branch on the stone',`<p>${id.includes('west')?'The western stone shows a broken outer ring and a branch bending east.':'The eastern stone shows the same broken ring. Its branch bends west.'} Together the branches embrace an empty center: the Son’s sign of an opened prison.</p><p>${b.west&&b.east?'Both impressions agree with the receipt. Take it to the bridge.':'The other impression is across this lower bank. No need to cross the water yet.'}</p>`);return true;}
  if(id==='q17-claim'){this.claim();return true;}
  if(id==='q17-quay-chest'){if(!b.open){this.claim();return true;}b.treasure=true;this.give('q17-quay-medallion');this.save();this.panel('The chest of the open quay','<p>Under coils of blue sail-thread lies a silver sun inside a broken ring. Harven lifts it into your palm.</p><p>“I kept counting,” he says. “The bond was gone, and I kept counting.” He takes down the toll slate. Behind you, the little river bell sounds for an arriving boat.</p>',this.button('q17-book','Read the quay’s five-page tale','bond')+this.button('q17-journal','See my next step'),'TREASURE FOUND');return true;}
  if(id==='q17-free-boatmaker'){this.panel('Harven','<p class="npc-role">Riverkin boatmaker · formerly held by the quay’s debt</p><p>“The voice in the ledger knew every mistake I had made. Some were true. Its claim that the Son had left me to pay again was the lie.”</p><p>“I have planks to return and apologies to make. Those are work I can do freely now.”</p>',this.button('q17-book','Read the quay’s tale','bond'));return true;}
  if(id==='q17-key'){if(a.returned){this.panel('The place beside the arch','<p>The key is back with Neris. A small white flower has opened beside the stone.</p>');return true;}a.key=true;this.give('q17-garden-key');this.save();this.panel('A key among the leaves','<p>A brass key lies beside the west pier. A leaf-shaped tag reads NERIS. The gardener is just north of the arch; Rook waits to the right of the path.</p>',this.button('q17-journal','Track this errand'));return true;}
  if(id==='q17-rook'){this.panel('Rook','<p class="npc-role">Young Carver · an impatient would-be friend</p><p>“Neris keeps saying, ‘Ask first.’ Give me her key. We can prove we belong here.” Rook lowers his voice. “If you’re really with us, don’t tell the keeper.”</p><p>The paths remain open. You can walk away, speak plainly, or ask Neris for help.</p>',this.button('q17-rook-choice','The key belongs to Neris','return',true)+this.button('q17-rook-choice','Let Rook use it without asking','yield')+this.button('q17-readings','Read before deciding','garden'),'THE GARDEN KEY');return true;}
  if(id==='q17-neris'){this.neris();return true;}
  if(['q17-spring-wheel','q17-west-wheel','q17-east-wheel'].includes(id)){this.wheel(['q17-spring-wheel','q17-west-wheel','q17-east-wheel'].indexOf(id));return true;}
  if(id==='q17-garden-chest'){if(!a.watered){this.panel('The seed-keeper’s chest','<p>A note under the lid: “These are for the planting, not a prize for borrowing my key. Ask me about the channels.” Neris waits beside the southern path.</p>',this.button('q17-journal','See the next step'));return true;}a.treasure=true;this.give('q17-seed-lantern');this.save();this.panel('A light for the growing things','<p>Neris unlocks the chest with her returned key and brings out a green-glass lantern and three seed envelopes. “For the road. Nothing lent against your name.”</p><p>Rook, who has been carrying the empty buckets, puts them down. “May I come tomorrow?”</p><p>“Ask tomorrow,” Neris says, smiling. “The western bed will need weeding.”</p>',this.button('q17-book','Read the garden’s five-page tale','garden')+this.button('q17-journal','See my next step'),'TREASURE FOUND');return true;}
  if(id==='q17-garden-story'){this.book('garden');return true;}
  return false;
 },
 claim(){const b=this.q().bond;if(b.open){this.panel('The slate is down','<p>The bridge is open. Harven’s chest rests on the northern mosaic.</p>');return;}this.panel('The second demand',`<p>A slate blocks the narrow bridge. From its black tally marks comes a dry whisper: “Paid once? Not enough. Make yourself worth the crossing.”</p><p>Harven looks at your receipt, then at his old ledger. “If I stop paying, what will become of all I have done?”</p><p>${!b.receipt?'Erelis, beside the bell lift in Brass Gully, has the King’s freely given receipt.':!b.west||!b.east?'Inspect both branch impressions along this lower bank. They identify the receipt; they do not settle another debt.':!b.recalled?'Read a passage before answering the whisper.':'The seal and both impressions agree. What claim will you carry across?'}</p>`,this.button('q17-readings','Read and remember','bond',true)+this.button('q17-bond-choice','The Son has already settled the bond','receipt')+this.button('q17-bond-choice','Offer to pay it again','pay'),'THE CANCELLED BOND');},
 neris(){const a=this.q().garden;this.panel('Neris',`<p class="npc-role">Carver gardener · keeper of this garden</p><p>“A friend need not buy a place beside me. The King’s Son gave me welcome before these beds were green.”</p><p>${!a.returned?'“The paths are open to visitors; my key opens the seed chest. It slipped beside the west pier of the arch. Please bring it back. Rook may visit, but he may not take what I have not offered.”':'“Thank you. The key stays with me. Will you help with the water? I can hold the intake while you turn the wheels.”'}</p><p>Three marks in the paths: <strong>spring wheel south ↓ · west wheel east → · east wheel south ↓</strong>. Follow the little channels. The chest by the northern path holds the planting lantern.</p>`,(!a.returned?this.button('q17-return-key','Give Neris her key','',true):this.button('q17-ask-help','Ask Neris to hold the intake','',true))+this.button('q17-readings','Read the words behind her welcome','garden')+this.button('q17-journal','Track the next step'),'THE GARDEN KEY');},
 wheel(i){const a=this.q().garden;if(!a.permission||!a.help){this.panel('A stiff wheel','<p>The intake will not hold by itself. Return the key to Neris, then ask her to work with you. The paths and grass remain open.</p>',this.button('q17-journal','See the next step'));return;}const names=['Spring','West','East'],dirs=['North ↑','East →','South ↓','West ←'];this.panel(names[i]+' wheel',`<p>The brass pointer faces <strong>${dirs[a.wheels[i]]}</strong>. Neris is holding the intake; take your time.</p><p>Carved instruction: ${['“From the spring, send the gift south.”','“From the west, share toward the heart.”','“At the east, send the overflow south to the common trough.”'][i]}</p>`,dirs.map((d,n)=>this.button('q17-turn',d,i+':'+n,n===a.wheels[i])).join(''),'WATER FOR THE GARDEN');},
 book(which,page=0){const book=TREASURE17_BOOKS[which]||TREASURE17_BOOKS.garden,pages=book.pages;page=Math.max(0,Math.min(4,page));this.panel(esc(book.title),`<div class="road-book"><p class="book-page">${esc(pages[page])}</p><p>${page+1} / 5 · Tideglass stories</p></div>`,(page<4?this.button('q17-book','Next page ▸',which+':'+(page+1),true):'')+(page?this.button('q17-book','◂ Previous',which+':'+(page-1)):''),'A BOOK FROM THE RIVER');},
 handle(action,id){const q=this.q(),b=q.bond,a=q.garden;
  if(action==='difficulty'&&g.exercise?.treasure17){const id=g.exercise.id;state.settings.difficulty=state.settings.difficulty==='hard'?'easy':'hard';this.save();this.recall(id);return true;}
  if(action==='q17-export'){download('Treasure-Trail-Readings.md',TREASURE17_SCRIPTURE_MD,'text/markdown');return true;}
  if(action==='q17-journal'){this.journal();return true;}if(action==='q17-readings'){this.readingMenu(id);return true;}if(action==='q17-read'){this.read(id);return true;}if(action==='q17-recall'){this.recall(id);return true;}if(action==='q17-book'){const [which,p]=id.split(':');this.book(which,Number(p)||0);return true;}
  if(action==='q17-bond-choice'){if(id==='pay'){this.panel('The tally adds another line','<p>The whisper moves the price before a coin can leave your hand. Nothing has been taken. Erelis taps the completed receipt. “A second payment cannot make the Son’s work more complete.”</p>',this.button('q17-claim','Look again at the receipt'));return true;}if(!b.receipt||!b.west||!b.east||!b.recalled){this.claim();return true;}b.open=true;this.sync();g.positionCache.clear();this.save();this.panel('The bridge stands open','<p>“The Son has already settled it.” You lay the receipt beside the two branch impressions.</p><p>The whisper thins to the sound of dry paper. Harven lifts the slate from the bridge. “Then let the boats come,” he says.</p><p>The chest is on the northern mosaic. Walk across the timber deck; the water beside it is deep.</p>');return true;}
  if(action==='q17-claim'){this.claim();return true;}
  if(action==='q17-rook-choice'){this.panel(id==='yield'?'Neris answers from the path':'The key stays its owner’s',id==='yield'?'<p>“No,” Neris says. “You may ask me, Rook. You may not make another person prove friendship by taking my key.” Rook steps back. The key is still yours to return; no treasure or card has been lost.</p>':'<p>“It belongs to Neris.” Rook looks away. You can return the key, speak with Neris, and offer willing help. Friendship is not a toll.</p>',this.button('q17-journal','Find the gardener'));return true;}
  if(action==='q17-return-key'){if(!a.key||!state.items.includes('q17-garden-key')){this.panel('Beside the west pier','<p>Neris points back to the arch. The brass key is among the leaves by its west pier.</p>');return true;}a.key=false;a.returned=true;a.permission=true;state.items=state.items.filter(i=>i!=='q17-garden-key');this.save();this.neris();return true;}
  if(action==='q17-ask-help'){if(!a.returned){this.neris();return true;}a.help=true;this.save();this.panel('Two hands at the intake','<p>“Gladly.” Neris takes her place at the intake. “Spring south, west east, east south. Tell me when you see the water reach the common trough.”</p><p>The work is offered freely. Read together before turning the last wheel.</p>',this.button('q17-readings','Read before the work','garden',true));return true;}
  if(action==='q17-turn'){const [i,n]=id.split(':').map(Number);if(!a.help||!a.permission||!Number.isInteger(i)||i<0||i>2||!Number.isInteger(n)||n<0||n>3)return true;a.wheels[i]=n;if(a.wheels.join()==='2,1,2'&&a.recalled){a.watered=true;this.save();this.panel('Water beyond the beds','<p>The channels fill. Clear water runs past the planted beds to the common trough. Rook brings an empty bucket and waits beside Neris.</p><p>“The chest by the northern path,” she says. “Take the lantern for your road.”</p>');}else{this.save();this.wheel(i);if(a.wheels.join()==='2,1,2')toast('The wheels agree. Read and remember with Neris before opening the intake.');}return true;}
  return false;
 },
 entities(){const s=state.region,q=this.q();if(s==='freed-quay')return q.bond.open?[]:[{x:50,y:53.8,q17Kind:'barrier'}];if(s==='lantern-garden')return [[50,37],[26,47],[74,47]].map(([x,y],i)=>({x,y,q17Kind:'wheel',i}));return[];},
 draw(p,x,y,h){if(p.q17Kind==='barrier'){BattleArt.sign({style:'carver',boards:[['A Second Toll','up'],['Show the Bond','up']]},x,y,h*.8);return true;}if(p.q17Kind==='wheel'){ctx.save();ctx.strokeStyle='#aa8b48';ctx.lineWidth=Math.max(2,h*.024);ctx.beginPath();ctx.ellipse(x,y-h*.08,h*.21,h*.13,0,0,Math.PI*2);ctx.stroke();const dirs=[[0,-1],[1,0],[0,1],[-1,0]],d=dirs[this.q().garden.wheels[p.i]];ctx.strokeStyle='#edcf7a';ctx.beginPath();ctx.moveTo(x,y-h*.08);ctx.lineTo(x+d[0]*h*.18,y-h*.08+d[1]*h*.11);ctx.stroke();ctx.restore();return true;}if(p.entry&&['q17-west-seal','q17-east-seal','q17-quay-chest','q17-garden-chest','q17-key'].includes(p.entry.id)){if(p.entry.id==='q17-key'){if(this.q().garden.returned)return true;const im=this.images.get('garden-key');if(im?.complete&&im.naturalWidth){const H=h*.4,W=H*im.naturalWidth/im.naturalHeight;ctx.drawImage(im,x-W/2,y-H,W,H);}return true;}sprite('chest',x,y,h*.65);return true;}return false;},
 objective(){const q=this.q();if(state.region==='freed-quay')return q.bond.open?'The quay is free · northern chest · south returns to Brass Gully':'The Cancelled Bond · two branch impressions, then the bridge';if(state.region==='lantern-garden')return q.garden.watered?'The water runs · find the northern chest · south returns to the orchard':'The Garden Key · return Neris’s key, ask for help, follow the channels';return null;},
 boot(){const keyImage=new Image();keyImage.src=TREASURE17_ART['garden-key'].asset;this.images.set('garden-key',keyImage);const originalByID=byID;byID=id=>originalByID(id)||this.passages.find(c=>c.id===id);Object.assign(Journey.objects,this.items);this.sync();const visit=Leaf.visit;Leaf.visit=id=>this.visit(id)||visit.call(Leaf,id);const handle=Adventure.handle;Adventure.handle=(a,id)=>this.handle(a,id)||handle.call(Adventure,a,id);const recalled=Adventure.recalled;Adventure.recalled=ex=>this.recalled(ex)||recalled.call(Adventure,ex);const entities=Adventure.entities;Adventure.entities=()=>[...entities.call(Adventure),...this.entities()];const draw=Adventure.drawEntity;Adventure.drawEntity=(...args)=>this.draw(...args)||draw.call(Adventure,...args);const sync=Adventure.sync;Adventure.sync=()=>{sync.call(Adventure);this.sync();};const objective=openingObjective;openingObjective=()=>this.objective()||objective();
  // Legacy outer-road portals preserve their actual departure heading.
  for(const e of events)if(e.kind==='portal'&&e.target){const id=e.id;if(/(?:^|-)west$/.test(id)||id==='silvermere-west')e.target.facing='left';else if(/(?:^|-)east$/.test(id)||id==='silver-east-road')e.target.facing='right';else if(/(?:^|-)south$/.test(id)||id==='silver-south-trail')e.target.facing='down';}
 }
};
const treasure17Restore=Road.restore.bind(Road);Road.restore=function(raw,...args){const s=treasure17Restore(raw,...args);s.treasure17=Treasure17.restore(raw?.treasure17);Treasure17.applyGate(s.treasure17);if(s.region==='freed-quay'&&raw?.region==='freed-quay'&&raw.player&&Number.isFinite(raw.player.x)&&Number.isFinite(raw.player.y)&&Exploration.free(raw.player,OPENING_WORLD.regions['freed-quay'].terrain,true))s.player={x:raw.player.x,y:raw.player.y};for(const id of Object.keys(Treasure17.items))if(Array.isArray(raw?.items)&&raw.items.includes(id)&&!s.items.includes(id))s.items.push(id);return s;};
